CREATE TABLE topic (
    id INTEGER PRIMARY KEY,
    title TEXT NOT NULL UNIQUE,
    minutes INTEGER NOT NULL CHECK (minutes >= 0)
);
INSERT INTO topic (title, minutes) VALUES ('Arrays', 25), ('Loops', 15);
SELECT title, minutes FROM topic ORDER BY id;

CREATE TABLE progress (id INTEGER PRIMARY KEY, points INTEGER NOT NULL);
INSERT INTO progress VALUES (1, 10), (2, 5);
BEGIN;
  UPDATE progress SET points = points - 2 WHERE id = 1;
  UPDATE progress SET points = points + 2 WHERE id = 2;
COMMIT;
SELECT id, points FROM progress ORDER BY id;

CREATE TABLE note (id INTEGER PRIMARY KEY, category TEXT, title TEXT);
CREATE INDEX note_category ON note(category);
INSERT INTO note (category, title)
    VALUES ('java', 'Collections'), ('sql', 'Joins');
EXPLAIN QUERY PLAN SELECT title FROM note WHERE category = 'sql';
SELECT title FROM note WHERE category = 'sql';

PRAGMA foreign_keys = ON;
CREATE TABLE topic (id INTEGER PRIMARY KEY, title TEXT NOT NULL);
CREATE TABLE attempt (
    id INTEGER PRIMARY KEY,
    topic_id INTEGER NOT NULL REFERENCES topic(id),
    score INTEGER NOT NULL CHECK (score >= 0)
);
INSERT INTO topic VALUES (1, 'Arrays');
INSERT INTO attempt VALUES (1, 1, 8);
SELECT topic.title, attempt.score
FROM topic JOIN attempt ON attempt.topic_id = topic.id;

WITH attempt(id, topic, minutes) AS (
    VALUES (1, 'Arrays', 8), (2, 'Loops', 5), (3, 'Arrays', 12)
)
SELECT id, topic, minutes,
       SUM(minutes) OVER (
           PARTITION BY topic ORDER BY id
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
       ) AS topic_total
FROM attempt
ORDER BY id;
